from pathlib import Path
import re

path = Path("index.html")
text = path.read_text(encoding="utf-8")

new_css = r'''.status-thermo-wrap{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.status-thermo-card{border:1px solid #d8e3f2;background:#fff;border-radius:14px;padding:14px 15px;min-width:0}.status-thermo-card+.status-thermo-card{border-left-color:#d8e3f2}.status-thermo-head{display:flex;justify-content:space-between;gap:10px;align-items:flex-start;margin-bottom:12px}.status-thermo-title{font-size:12.5px;font-weight:850;color:#17233e}.status-thermo-total{font-size:10.5px;color:#71819e;font-weight:760;white-space:nowrap}.status-thermo-body{display:grid;grid-template-columns:74px minmax(0,1fr);gap:14px;align-items:center}.status-thermo-axis{display:grid;grid-template-columns:24px 34px;gap:8px;align-items:stretch;height:160px}.status-thermo-scale{display:flex;flex-direction:column;justify-content:space-between;align-items:flex-end;font-size:9.5px;color:#7d8ca5;font-weight:700;padding:1px 0}.status-thermo-track{height:160px;border:1px solid #cfdbea;border-radius:12px;overflow:hidden;background:#edf2f8;display:flex;flex-direction:column}.status-thermo-seg{width:100%}.status-thermo-seg.pending-rem{background:#f4bd72}.status-thermo-seg.pending-man{background:#ef8b95}.status-thermo-seg.done{background:#1cae7a}.status-thermo-copy{min-width:0}.status-thermo-main{display:flex;align-items:baseline;gap:6px;margin-bottom:4px}.status-thermo-pct{font-size:24px;line-height:1;font-weight:880;letter-spacing:-.035em;color:#159a6c}.status-thermo-label{font-size:10.5px;font-weight:760;color:#657895}.status-thermo-pending{display:flex;align-items:center;gap:6px;font-size:10.5px;font-weight:800;margin-bottom:12px}.status-thermo-pending.rem{color:#c77812}.status-thermo-pending.man{color:#d94a57}.status-thermo-pending i{width:7px;height:7px;border-radius:50%;display:inline-block;background:currentColor}.status-thermo-stats{display:grid;gap:7px}.status-thermo-stat{border:1px solid #dce6f4;background:#f9fbfe;border-radius:10px;padding:8px 10px;display:flex;align-items:center;justify-content:space-between;gap:10px;min-height:38px}.status-thermo-stat span{font-size:10.5px;color:#61728e;font-weight:760}.status-thermo-stat strong{font-size:13px;color:#17233e}.status-thermo-stat.od-clickable{cursor:pointer}.status-thermo-stat.od-clickable:hover{border-color:#b7c9e4;background:#f4f8fe}.status-thermo-stat.is-active{box-shadow:inset 0 0 0 1px #9eb7e7;background:#f4f8fe}.status-panel-sub{font-size:10.5px;color:#71819e;margin:-4px 0 12px}.text-purple{color:var(--violet)}.text-orange{color:var(--orange)}.text-green{color:var(--green)}.text-red{color:var(--red)}
#statusPanel{padding:14px 16px 15px}#statusPanel h3{font-size:13px;margin-bottom:8px;color:#17233e}
@media(max-width:900px){.status-thermo-wrap{grid-template-columns:1fr}.status-thermo-body{grid-template-columns:66px minmax(0,1fr)}}'''

css_pattern = re.compile(r"\.status-focus-list\{.*?#statusPanel h3\{[^}]*\}", re.S)
text, css_count = css_pattern.subn(new_css, text, count=1)
if css_count != 1:
    raise SystemExit(f"Expected one status CSS block, found {css_count}")

new_js = r'''function renderStatus(){var a=rows(false),m=countBy(a,'status'),d=m.Cumplido||0,p=m.Pendiente||0,t=d+p,active=$('filterState').value,md={},mp={};a.forEach(function(x){if(x.status==='Cumplido')md[x.manifest]=1;if(x.status==='Pendiente')mp[x.manifest]=1});var manDone=Object.keys(md).length,manPend=Object.keys(mp).length,manTotal=manDone+manPend,remDonePct=pct(d,t),remPendPct=pct(p,t),manDonePct=pct(manDone,manTotal),manPendPct=pct(manPend,manTotal);$('statusTitle').textContent='Cumplimiento operativo';$('statusContent').innerHTML='<div class="status-panel-sub">Remesas y manifiestos según los filtros actuales</div><div class="status-thermo-wrap"><section class="status-thermo-card"><div class="status-thermo-head"><div class="status-thermo-title">Remesas</div><div class="status-thermo-total">'+t+' total</div></div><div class="status-thermo-body"><div class="status-thermo-axis"><div class="status-thermo-scale"><span>100%</span><span>0%</span></div><div class="status-thermo-track"><div class="status-thermo-seg pending-rem" style="height:'+remPendPct+'%"></div><div class="status-thermo-seg done" style="height:'+remDonePct+'%"></div></div></div><div class="status-thermo-copy"><div class="status-thermo-main"><span class="status-thermo-pct">'+remDonePct+'%</span><span class="status-thermo-label">cumplidas</span></div><div class="status-thermo-pending rem"><i></i><span>'+remPendPct+'% por cumplir</span></div><div class="status-thermo-stats"><button class="status-thermo-stat od-clickable '+(active==='Cumplido'?'is-active':'')+'" data-st="Cumplido"><span>Cumplidas</span><strong>'+d+'</strong></button><button class="status-thermo-stat od-clickable '+(active==='Pendiente'?'is-active':'')+'" data-st="Pendiente"><span>Por cumplir</span><strong>'+p+'</strong></button></div></div></div></section><section class="status-thermo-card"><div class="status-thermo-head"><div class="status-thermo-title">Manifiestos</div><div class="status-thermo-total">'+manTotal+' total</div></div><div class="status-thermo-body"><div class="status-thermo-axis"><div class="status-thermo-scale"><span>100%</span><span>0%</span></div><div class="status-thermo-track"><div class="status-thermo-seg pending-man" style="height:'+manPendPct+'%"></div><div class="status-thermo-seg done" style="height:'+manDonePct+'%"></div></div></div><div class="status-thermo-copy"><div class="status-thermo-main"><span class="status-thermo-pct">'+manDonePct+'%</span><span class="status-thermo-label">cumplidos</span></div><div class="status-thermo-pending man"><i></i><span>'+manPendPct+'% por cumplir</span></div><div class="status-thermo-stats"><div class="status-thermo-stat"><span>Cumplidos</span><strong>'+manDone+'</strong></div><div class="status-thermo-stat"><span>Por cumplir</span><strong>'+manPend+'</strong></div></div></div></div></section></div>';Array.from($('statusContent').querySelectorAll('[data-st]')).forEach(function(b){b.addEventListener('click',function(){var s=this.dataset.st;$('filterState').value=$('filterState').value===s?'':s;if(s!=='Pendiente')state.aging='';renderAll()})})}
var ac='''

js_pattern = re.compile(r"function renderStatus\(\)\{.*?\}\nvar ac=", re.S)
text, js_count = js_pattern.subn(new_js, text, count=1)
if js_count != 1:
    raise SystemExit(f"Expected one renderStatus function, found {js_count}")

path.write_text(text, encoding="utf-8")
print("Patched index.html successfully")
